-- Seed: Insert all Spanish municipalities from INE
-- Total: 8132 municipalities
-- Generated from scripts/data/municipios-ine.json

CREATE OR REPLACE FUNCTION upsert_municipio(
  p_codigo_ine CHAR(5),
  p_nombre TEXT,
  p_provincia_codigo TEXT,
  p_poblacion INTEGER,
  p_lng DOUBLE PRECISION,
  p_lat DOUBLE PRECISION
) RETURNS VOID AS $$
DECLARE
  v_provincia_id UUID;
BEGIN
  SELECT id INTO v_provincia_id FROM provincias WHERE codigo_ine = p_provincia_codigo;
  IF v_provincia_id IS NULL THEN
    RAISE NOTICE 'Provincia % not found for %', p_provincia_codigo, p_nombre;
    RETURN;
  END IF;

  INSERT INTO municipios (codigo_ine, nombre, provincia_id, poblacion, geom)
  VALUES (p_codigo_ine, p_nombre, v_provincia_id, p_poblacion, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326))
  ON CONFLICT (codigo_ine)
  DO UPDATE SET
    nombre = EXCLUDED.nombre,
    poblacion = EXCLUDED.poblacion,
    geom = EXCLUDED.geom;
END;
$$ LANGUAGE plpgsql;

