-- Verification queries
SELECT COUNT(*) as total_municipios FROM municipios;
SELECT p.nombre as provincia, COUNT(m.id) as num_municipios
FROM provincias p
LEFT JOIN municipios m ON m.provincia_id = p.id
GROUP BY p.nombre
ORDER BY num_municipios DESC;